function decodeQuality(text: string): number {
  const replacement = (text.match(/\uFFFD/g) || []).length;
  const mojibake = (text.match(/\u00C3|\u00E6|\u00E9|\u00EF|\u00E5/g) || []).length;
  return replacement * 10 + mojibake * 3;
}

async function readDbcFileText(file: File): Promise<string> {
  const bytes = new Uint8Array(await file.arrayBuffer());

  if (bytes.length >= 2) {
    if (bytes[0] === 0xff && bytes[1] === 0xfe) {
      return new TextDecoder('utf-16le').decode(bytes);
    }
    if (bytes[0] === 0xfe && bytes[1] === 0xff) {
      return new TextDecoder('utf-16be').decode(bytes);
    }
  }

  const tryDecode = (encoding: string, fatal = false): string | null => {
    try {
      return new TextDecoder(encoding, { fatal }).decode(bytes);
    } catch {
      return null;
    }
  };

  const utf8Strict = tryDecode('utf-8', true);
  if (utf8Strict && decodeQuality(utf8Strict) === 0) return utf8Strict;

  const utf8 = utf8Strict ?? tryDecode('utf-8', false) ?? '';
  const gb18030 = tryDecode('gb18030', false) ?? '';

  if (!gb18030) return utf8;
  return decodeQuality(gb18030) < decodeQuality(utf8) ? gb18030 : utf8;
}

